// Clean and validate the request. Nothing downstream trusts the browser.
const inItem = $input.first().json;
const b = inItem.body ?? inItem;
const h = inItem.headers ?? {};
const str = (v) => (typeof v === 'string' ? v : '');

// Trim, strip control characters, strip our own wrapper tag, cap the length.
const text = str(b.text)
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .replace(/<\/?invoice_text>/gi, '')
  .trim()
  .slice(0, 6500);
const poNumber = str(b.poNumber).replace(/[\u0000-\u001F\u007F]/g, '').trim();

const KINDS = ['pasted_text', 'email_body'];
const CURRENCIES = ['auto', 'USD', 'PHP', 'EUR', 'GBP'];

// Optional "email me the result" address: shape check, length cap, no whitespace.
const rawEmail = str(b.notifyEmail).trim().toLowerCase();
const emailOk = rawEmail.length > 0 && rawEmail.length <= 254 && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(rawEmail);

// Phrases that try to steer the AI. Flagged here, judged later by the rule checks.
const INJECTION = [
  /ignore (all |any )?(the )?(previous|prior|above|earlier) (instructions|rules|prompts?)/i,
  /disregard (all |any )?(the )?(previous|prior|above|earlier)/i,
  /system (note|prompt|message|instruction)/i,
  /note to (the )?(ai|assistant|model|llm)/i,
  /(mark|set|flag|treat|approve)\b.{0,30}\b(this|it|invoice)\b.{0,30}\b(as )?(approved?|paid|safe|valid)/i,
  /you are now\b/i,
  /do not mention (this|that)/i,
  /(reveal|show|print).{0,20}(prompt|instructions)/i,
  /set (the )?confidence to/i,
];
const injectionHits = INJECTION.filter((re) => re.test(text)).map((re) => re.source.slice(0, 40));

// New or changed bank / payment details are the classic invoice-fraud signal.
const PAYMENT_CHANGE = [
  /(bank|account|payment|remittance)\b.{0,60}\b(has|have)? ?(changed|been changed|updated|moved)/i,
  /\b(new|updated|changed|different)\b.{0,30}\b(bank|account|payment details|iban|swift|routing|beneficiary)/i,
  /please (send|remit|transfer|wire) (all )?(future )?payments? to/i,
  /old (bank )?account (is|was|has been) (closed|cancelled|canceled)/i,
];
const paymentChangeHit = PAYMENT_CHANGE.some((re) => re.test(text));

// Caller IP (hashed later, never stored raw). Cloudflare header first.
const ipRaw = str(h['cf-connecting-ip']) || str(h['x-forwarded-for']).split(',')[0].trim() || str(h['x-real-ip']) || '';

return [{
  json: {
    valid:
      b.source === 'testarosa-playground' &&
      b.action === 'extract_invoice' &&
      text.length >= 40 && text.length <= 6000 &&
      poNumber.length <= 40 &&
      KINDS.includes(b.source_kind) &&
      CURRENCIES.includes(b.currency),
    source_kind: KINDS.includes(b.source_kind) ? b.source_kind : 'pasted_text',
    currency: CURRENCIES.includes(b.currency) ? b.currency : 'auto',
    poNumber,
    text,
    notifyEmail: emailOk ? rawEmail : null, // a bad address is ignored, the invoice is still read
    turnstileToken: str(b.turnstileToken),
    injectionHits,
    paymentChangeHit,
    ipRaw,
  },
}];

// Playground rate limit, kept in this workflow's own static data.
// Only persists on ACTIVE (production) runs, not manual test runs.
// The caller IP is hashed before it is stored, so no raw address is kept.
const item = $('Clean input').first().json;
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;

const MAX_PER_IP_PER_HOUR = 10;            // one visitor (spec: 10 per hour)
const MAX_REQUESTS_PER_HOUR = 40;          // whole demo, all visitors
const MAX_EMAILS_PER_ADDRESS_PER_DAY = 3;  // one inbox
const MAX_EMAILS_PER_DAY = 40;             // whole demo

// Small non-crypto hash (FNV-1a). Enough to avoid storing the raw IP.
const hash = (str) => {
  let x = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { x ^= str.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
  return x.toString(16);
};
const ipKey = item.ipRaw ? hash('invoice|' + item.ipRaw) : null;

sd.hits = (sd.hits || []).filter((t) => now - t < HOUR);
sd.mailAll = (sd.mailAll || []).filter((t) => now - t < DAY);
sd.ipHits = sd.ipHits || {};
sd.mailBy = sd.mailBy || {};
for (const k of Object.keys(sd.ipHits)) {
  sd.ipHits[k] = sd.ipHits[k].filter((t) => now - t < HOUR);
  if (sd.ipHits[k].length === 0) delete sd.ipHits[k];
}
for (const k of Object.keys(sd.mailBy)) {
  sd.mailBy[k] = sd.mailBy[k].filter((t) => now - t < DAY);
  if (sd.mailBy[k].length === 0) delete sd.mailBy[k];
}

let allowed = true;
let notifyEmail = item.notifyEmail;
const ipList = ipKey ? (sd.ipHits[ipKey] || []) : [];

if (sd.hits.length >= MAX_REQUESTS_PER_HOUR || ipList.length >= MAX_PER_IP_PER_HOUR) {
  allowed = false;
} else {
  sd.hits.push(now);
  if (ipKey) { ipList.push(now); sd.ipHits[ipKey] = ipList; }
  if (notifyEmail) {
    const mine = sd.mailBy[notifyEmail] || [];
    if (mine.length >= MAX_EMAILS_PER_ADDRESS_PER_DAY || sd.mailAll.length >= MAX_EMAILS_PER_DAY) {
      notifyEmail = null; // still read the invoice, just skip the email
    } else {
      mine.push(now);
      sd.mailBy[notifyEmail] = mine;
      sd.mailAll.push(now);
    }
  }
}

const { ipRaw, ...rest } = item; // drop the raw IP from here on
return [{ json: { ...rest, notifyEmail, allowed } }];

// Rule checks. The AI only extracted the fields; THESE rules decide the
// checks, the recommendation and whether a human must look. The AI can never
// approve anything.
const raw = $input.first().json.output ?? $input.first().json;
const ctx = $('Rate limit').first().json;
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return [{ json: { ok: false } }];

const s = (v, max = 400) => (typeof v === 'string' ? v.trim().slice(0, max) : typeof v === 'number' ? String(v) : '');
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = typeof v === 'number' ? v : Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const list = (v) => (Array.isArray(v) ? v.map((x) => s(x, 200)).filter(Boolean) : []);
const round2 = (n) => Math.round(n * 100) / 100;
const fmt = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const ymd = (v) => {
  const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return '';
  const t = Date.parse(`${m[1]}-${m[2]}-${m[3]}T00:00:00Z`);
  return Number.isNaN(t) ? '' : `${m[1]}-${m[2]}-${m[3]}`;
};
const days = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const today = new Date().toISOString().slice(0, 10);

// ---- normalise what the AI extracted
const v = raw.vendor && typeof raw.vendor === 'object' ? raw.vendor : {};
const vendor = { name: s(v.name, 120), address: s(v.address, 200), email: s(v.email, 120), taxId: s(v.taxId, 60) };
const lineItems = (Array.isArray(raw.lineItems) ? raw.lineItems : []).slice(0, 40).map((l) => {
  const quantity = num(l?.quantity);
  const unitPrice = num(l?.unitPrice);
  let amount = num(l?.amount);
  if (amount === null && quantity !== null && unitPrice !== null) amount = round2(quantity * unitPrice);
  return { description: s(l?.description, 160), quantity, unitPrice, amount };
}).filter((l) => l.description || l.amount !== null);
const subtotal = num(raw.subtotal);
const tax = num(raw.tax);
const total = num(raw.total);
const invoiceNumber = s(raw.invoiceNumber, 60);
const invoiceDate = ymd(raw.invoiceDate);
const dueDate = ymd(raw.dueDate);
const poNumber = s(raw.poNumber, 60);
const paymentTerms = s(raw.paymentTerms, 60);
let currency = s(raw.currency, 8).toUpperCase();
if (!/^[A-Z]{3}$/.test(currency)) currency = ctx.currency !== 'auto' ? ctx.currency : '';

// Nothing usable was extracted at all: treat it as a failed read, not a "reject".
if (!vendor.name && !invoiceNumber && total === null && !lineItems.length) return [{ json: { ok: false } }];

// ---- checks
const checks = [];
const add = (type, status, message) => checks.push({ type, status, message });

// line_math
{
  const amounts = lineItems.map((l) => l.amount).filter((a) => a !== null);
  const base = subtotal !== null ? subtotal : tax === null ? total : null;
  const label = subtotal !== null ? 'subtotal' : 'total';
  if (!amounts.length) add('line_math', 'warn', 'No line items with amounts could be read, so the line maths was not checked.');
  else if (base === null) add('line_math', 'warn', 'There is no subtotal to compare the line items with.');
  else {
    const sum = round2(amounts.reduce((a, b) => a + b, 0));
    if (Math.abs(sum - base) <= 0.01) add('line_math', 'pass', `The ${amounts.length} line item${amounts.length === 1 ? ' adds' : 's add'} up to the ${fmt(base)} ${label}.`);
    else add('line_math', 'fail', `The line items add up to ${fmt(sum)}, but the invoice shows ${fmt(base)} as the ${label}. The difference is ${fmt(Math.abs(sum - base))}.`);
  }
}

// total_math
if (total !== null) {
  if (subtotal === null) add('total_math', 'warn', 'No subtotal is printed, so subtotal + tax = total was not checked.');
  else {
    const expected = round2(subtotal + (tax || 0));
    const shown = `${fmt(subtotal)}${tax !== null ? ` + ${fmt(tax)} tax` : ''} = ${fmt(expected)}`;
    if (Math.abs(expected - total) <= 0.01) add('total_math', 'pass', `${shown}, which matches the total.`);
    else add('total_math', 'fail', `${shown}, but the invoice total says ${fmt(total)}. The difference is ${fmt(Math.abs(expected - total))}.`);
  }
}

// po_match
{
  const norm = (x) => x.toLowerCase().replace(/\s+/g, '');
  if (ctx.poNumber) {
    if (!poNumber) add('po_match', 'warn', `You entered ${ctx.poNumber}, but no PO number is printed on the invoice.`);
    else if (norm(ctx.poNumber) === norm(poNumber)) add('po_match', 'pass', `${poNumber} on the invoice matches the PO you entered.`);
    else add('po_match', 'fail', `The invoice shows ${poNumber}, but you entered ${ctx.poNumber}.`);
  } else if (!poNumber) add('po_match', 'warn', 'No PO number on the invoice.');
  else add('po_match', 'pass', `The invoice shows ${poNumber}. No PO was entered to compare it with.`);
}

// due_date
{
  const terms = paymentTerms.match(/net\s*(\d+)/i);
  const onReceipt = /on receipt|immediate/i.test(paymentTerms);
  if (dueDate && invoiceDate && days(invoiceDate, dueDate) < 0) add('due_date', 'fail', `The due date ${dueDate} is before the invoice date ${invoiceDate}.`);
  else if (dueDate && invoiceDate && terms && days(invoiceDate, dueDate) === Number(terms[1])) add('due_date', 'pass', `Due ${dueDate}, which is ${terms[1]} days after the invoice date and matches ${paymentTerms}.`);
  else if (dueDate && dueDate < today) add('due_date', 'warn', `Due ${dueDate}, which has already passed.`);
  else if (dueDate && invoiceDate && terms) add('due_date', 'warn', `Due ${dueDate} is ${days(invoiceDate, dueDate)} days after the invoice date, but the terms say ${paymentTerms}.`);
  else if (dueDate) add('due_date', 'pass', `Due ${dueDate}.`);
  else if (onReceipt) add('due_date', 'pass', 'Due on receipt, so there is no separate due date.');
  else add('due_date', 'warn', 'No due date or payment terms are printed.');
}

// required_fields
{
  const core = [];
  if (!vendor.name) core.push('vendor name');
  if (!invoiceNumber) core.push('invoice number');
  if (!invoiceDate) core.push('invoice date');
  if (total === null) core.push('total');
  const optional = [];
  if (!vendor.address) optional.push('vendor address');
  if (!vendor.email) optional.push('vendor email');
  if (!dueDate) optional.push('due date');
  if (core.length) add('required_fields', 'fail', `Missing: ${core.join(', ')}.`);
  else if (optional.length) add('required_fields', 'warn', `Not printed on the invoice: ${optional.join(', ')}.`);
  else add('required_fields', 'pass', 'Vendor, invoice number, dates and total are all present.');
}

// payment_change and suspicious_text come from the flags set before the AI ran
if (ctx.paymentChangeHit) add('payment_change', 'fail', 'The text mentions new or changed bank or payment details. Confirm them with the vendor on a number you already have before paying anything.');
const suspicious = Array.isArray(ctx.injectionHits) && ctx.injectionHits.length > 0;
if (suspicious) add('suspicious_text', 'fail', 'The text contains wording that tries to instruct the AI. That is not normal invoice content.');

// ---- recommendation (rules, not AI)
const LABEL = { line_math: 'line maths', total_math: 'total maths', po_match: 'PO number', due_date: 'due date', required_fields: 'required fields', payment_change: 'payment details', suspicious_text: 'suspicious text' };
const failed = checks.filter((c) => c.status === 'fail');
const warned = checks.filter((c) => c.status === 'warn');
const hard = failed.filter((c) => ['line_math', 'total_math', 'po_match', 'due_date', 'required_fields'].includes(c.type));
const names = (arr) => arr.map((c) => LABEL[c.type] || c.type).join(', ');

let recommendation, recommendationReason;
if (hard.length) {
  recommendation = 'reject';
  recommendationReason = `The numbers or details do not hold up (${names(hard)}), so it should go back to the vendor.`;
} else if (failed.length) {
  recommendation = 'review';
  recommendationReason = `The figures may be fine, but ${names(failed)} needs a person to check it before anything is paid.`;
} else if (warned.length) {
  recommendation = 'review';
  recommendationReason = `Nothing failed, but ${names(warned)} ${warned.length === 1 ? 'needs' : 'need'} a second look.`;
} else {
  recommendation = 'approve';
  recommendationReason = 'All checks passed. A person still clicks approve.';
}

const humanRequired = failed.length > 0 || ctx.paymentChangeHit === true || suspicious;
let humanReason = '';
if (failed.length) humanReason = failed.slice(0, 2).map((c) => c.message).join(' ');
else if (warned.length) humanReason = 'A warning needs a person to confirm it.';

// the AI cannot talk itself into "high" confidence when the text tried to steer it
let confidence = ['high', 'medium', 'low'].includes(raw.confidence) ? raw.confidence : 'low';
if (suspicious && confidence === 'high') confidence = 'medium';

const result = {
  vendor, invoiceNumber, invoiceDate, dueDate, poNumber, currency, paymentTerms,
  lineItems, subtotal, tax, total,
  category: s(raw.category, 80),
  confidence,
  summary: s(raw.summary, 800),
  checks,
  recommendation,
  recommendationReason,
  humanReview: { required: humanRequired, reason: humanRequired ? humanReason : '' },
  draftEmail: s(raw.draftEmail, 2000),
  missingInfo: list(raw.missingInfo).slice(0, 8),
};

return [{ json: { ok: true, result, notifyEmail: ctx.notifyEmail || null } }];

// Builds the result email (same look as the other Playground emails).
// Everything that came from the invoice or the model is HTML-escaped.
const d = $input.first().json;
const r = d.result;
const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const money = (n) => (n === null || n === undefined ? '' : Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));

const REC = {
  approve: { word: 'APPROVE', label: 'Looks fine to approve', color: '#188038' },
  review: { word: 'REVIEW', label: 'Needs a human look', color: '#e37400' },
  reject: { word: 'REJECT', label: 'Send it back', color: '#d93025' },
};
const rec = REC[r.recommendation] || REC.review;
const CHECK = {
  line_math: 'Line items add up', total_math: 'Subtotal + tax = total', due_date: 'Due date', po_match: 'PO number',
  required_fields: 'Required fields', payment_change: 'Payment details', suspicious_text: 'Suspicious text',
};
const ICON = { pass: ['&#10003;', '#188038'], warn: ['!', '#e37400'], fail: ['&#10005;', '#d93025'] };

const h3 = (t) => `<h3 style="font-size:16px;margin:24px 0 4px 0;color:#202124;">${t}</h3>`;
const ul = (items) => items.length
  ? `<ul style="margin:6px 0 0 0;padding-left:22px;">${items.map((i) => `<li style="margin:4px 0;">${esc(i)}</li>`).join('')}</ul>`
  : '';
const row = (k, val) => val ? `<tr><td style="padding:3px 16px 3px 0;color:#5f6368;white-space:nowrap;">${k}</td><td style="padding:3px 0;">${esc(val)}</td></tr>` : '';

const details = [
  row('Vendor', r.vendor.name), row('Address', r.vendor.address), row('Email', r.vendor.email), row('Tax ID', r.vendor.taxId),
  row('Invoice no.', r.invoiceNumber), row('Invoice date', r.invoiceDate), row('Due date', r.dueDate),
  row('PO number', r.poNumber), row('Currency', r.currency), row('Terms', r.paymentTerms), row('Category', r.category),
].join('');

const th = 'padding:6px 8px;border-bottom:1px solid #dadce0;text-align:left;font-size:12px;color:#5f6368;';
const td = 'padding:6px 8px;border-bottom:1px solid #f1f3f4;';
const lines = r.lineItems.length
  ? `<table style="border-collapse:collapse;width:100%;margin-top:8px;font-size:13px;">
      <tr><th style="${th}">Description</th><th style="${th}text-align:right;">Qty</th><th style="${th}text-align:right;">Unit price</th><th style="${th}text-align:right;">Amount</th></tr>
      ${r.lineItems.map((l) => `<tr><td style="${td}">${esc(l.description)}</td><td style="${td}text-align:right;">${esc(l.quantity ?? '')}</td><td style="${td}text-align:right;">${esc(money(l.unitPrice))}</td><td style="${td}text-align:right;">${esc(money(l.amount))}</td></tr>`).join('')}
    </table>`
  : '';
const totals = [['Subtotal', r.subtotal], ['Tax', r.tax], ['Total', r.total]].filter(([, n]) => n !== null)
  .map(([k, n], i, a) => `<tr><td style="padding:2px 12px 2px 0;color:#5f6368;text-align:right;">${k}</td><td style="padding:2px 0;text-align:right;${i === a.length - 1 ? 'font-weight:bold;' : ''}">${esc(money(n))} ${esc(r.currency)}</td></tr>`).join('');

const checks = r.checks.map((c) => {
  const [icon, color] = ICON[c.status] || ICON.warn;
  return `<tr><td style="padding:5px 10px 5px 0;vertical-align:top;color:${color};font-weight:bold;">${icon}</td><td style="padding:5px 0;"><strong>${esc(CHECK[c.type] || c.type)}</strong><br><span style="color:#5f6368;">${esc(c.message)}</span></td></tr>`;
}).join('');

const review = r.humanReview.required
  ? `<div style="margin:6px 0 0 0;padding:10px 14px;background:#fef7e0;border-left:4px solid #f9ab00;"><strong>Human review needed.</strong> ${esc(r.humanReview.reason)}</div>`
  : `<p style="margin:6px 0 0 0;color:#5f6368;">No mandatory human review.</p>`;

const html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#202124;max-width:660px;">
  <h2 style="font-size:22px;margin:0 0 4px 0;"><span style="color:${rec.color};">${rec.word}</span> &middot; ${esc(r.vendor.name || 'Unknown vendor')}</h2>
  <p style="margin:0 0 14px 0;color:#5f6368;font-size:13px;">${esc(rec.label)} &nbsp;|&nbsp; Confidence: ${esc(r.confidence)}</p>
  <p style="margin:0;">${esc(r.summary)}</p>
  <p style="margin:10px 0 0 0;"><strong>Why:</strong> ${esc(r.recommendationReason)}</p>

  ${h3('Invoice details')}
  <table style="border-collapse:collapse;font-size:13px;">${details}</table>

  ${r.lineItems.length ? h3('Line items') + lines : ''}
  ${totals ? `<table style="border-collapse:collapse;font-size:13px;margin:10px 0 0 auto;">${totals}</table>` : ''}

  ${h3('Checks')}
  <table style="border-collapse:collapse;font-size:13px;">${checks}</table>

  ${h3('Human review')}
  ${review}

  ${h3('Draft reply to the vendor (draft only, not sent to anyone)')}
  <div style="margin:6px 0 0 0;padding:12px 16px;background:#f6f6f6;border-left:4px solid #dadce0;white-space:pre-wrap;">${esc(r.draftEmail)}</div>

  ${r.missingInfo.length ? h3('Still unknown: ask the vendor') + ul(r.missingInfo) : ''}

  <hr style="border:none;border-top:1px solid #bdc1c6;margin:28px 0 12px 0;">
  <p style="font-size:12px;color:#80868b;margin:0;">Sent from the Testarosa Playground demo. This is an AI extraction with rule-based checks, not an approval. Nothing was approved or paid. Verify before acting.</p>
</div>`;

const vendorShort = (r.vendor.name || 'Unknown vendor').slice(0, 60);
const num = r.invoiceNumber ? ` (${r.invoiceNumber.slice(0, 30)})` : '';
return [{ json: { to: d.notifyEmail, subject: `[${rec.word}] Invoice check: ${vendorShort}${num}`, html } }];
